# Lattice webs, lead 4 (exact): the 4D permutohedron (corners = permutations of (0,1,2,3,4), centred), in the hyperplane sum x = 0 of R^5.
# It tiles by translations by the lattice generated by 5e_i - (1,1,1,1,1) (A4*, scaled). For each Vacuus family (hyperplanes through the
# centre and each 2-face) and Resonus family (through the centre parallel to each facet): h = max n.x over the cell, d = gap of n.Lattice,
# k = 2h/d; Theorem 0: the family continues exactly when k <= 2 (the cell is centrally symmetric).
from fractions import Fraction as F
from itertools import permutations, combinations
from math import gcd
import sys
N=int(sys.argv[1]) if len(sys.argv)>1 else 5
V=[tuple(F(p[i])-F(N-1,2) for i in range(N)) for p in permutations(range(N))]
def dot(a,b): return sum(x*y for x,y in zip(a,b))
gens=[tuple(F(N*(i==j)-1) for j in range(N)) for i in range(N)]
def prim(n):
    from math import lcm
    L=lcm(*[x.denominator for x in n]); m=[int(x*L) for x in n]; g=0
    for x in m: g=gcd(g,abs(x))
    m=[x//g for x in m]; k=next(x for x in m if x)
    return tuple(-x for x in m) if k<0 else tuple(m)
def null(rows):
    M=[list(r) for r in rows]; piv=[]; r0=0
    for c in range(N):
        p=next((i for i in range(r0,len(M)) if M[i][c]!=0),None)
        if p is None: continue
        M[r0],M[p]=M[p],M[r0]; M[r0]=[x/M[r0][c] for x in M[r0]]
        for i in range(len(M)):
            if i!=r0 and M[i][c]!=0: M[i]=[a-M[i][c]*b for a,b in zip(M[i],M[r0])]
        piv.append(c); r0+=1
    free=[c for c in range(N) if c not in piv]
    assert len(free)==1, (len(free))
    n=[F(0)]*N; n[free[0]]=F(1)
    for i,c in enumerate(piv): n[c]=-M[i][free[0]]
    return n
def rank(rows):
    M=[list(r) for r in rows]; r0=0
    for c in range(N):
        p=next((i for i in range(r0,len(M)) if M[i][c]!=0),None)
        if p is None: continue
        M[r0],M[p]=M[p],M[r0]
        for i in range(r0+1,len(M)):
            if M[i][c]!=0:
                f=M[i][c]/M[r0][c]; M[i]=[a-f*b for a,b in zip(M[i],M[r0])]
        r0+=1
    return r0
subsets=[S for r in range(1,N) for S in combinations(range(N),r)]
def face(Ss):   # vertices where each S in the chain holds the largest |S| values
    return [v for v in V if all(sorted([v[i] for i in S])==sorted(sorted(v)[-len(S):]) for S in Ss)]
facets=[S for S in subsets]
res=set(); vac=set(); n2=0
for S in facets:
    n=tuple(F(1 if i in S else 0)-F(len(S),N) for i in range(N)); res.add(prim(n))
for S,T in combinations(subsets,2):
    if set(S)<set(T) or set(T)<set(S):
        A,B=(S,T) if len(S)<len(T) else (T,S)
        Fv=face([A,B]); n2+=1
        rows=[tuple(F(1) for _ in range(N))]
        for w in Fv:
            if rank(rows+[w])>rank(rows): rows.append(w)
            if len(rows)==N-1: break
        assert len(rows)==N-1
        n=null(rows)
        vac.add(prim(n))
print('corners',len(V),'facets',len(facets),'2-faces',n2)
print('Resonus families',len(res),' Vacuus families',len(vac),' equal',res==vac)
def k_of(n):
    h=max(dot(n,v) for v in V); g=0
    for x in (dot(n,u) for u in gens): g=gcd(g,int(x)) if F(x).denominator==1 else None
    if g is None: return h,None,F(10**9)
    return h,g,F(2*h,g) if g else None
out={}
for lab,fam in (('Resonus',res),('Vacuus',vac)):
    for n in sorted(fam):
        h,d,k=k_of(n); out.setdefault((lab,k<=2),[]).append((n,h,d,k))
for (lab,ok),L in sorted(out.items()):
    print(f'{lab} {"CONTINUE" if ok else "BREAK"}: {len(L)} families; e.g. n={L[0][0]} h={L[0][1]} d={L[0][2]} k={L[0][3]}')
    print('   k values', sorted({str(x[3]) for x in L}))
ok_ctrl = (N==5 and len(res)==15 and n2==150) or (N==4 and len(res)==7 and n2==36)
print('FINAL ok' if ok_ctrl else 'FINAL FAIL (facet or 2-face count)')
